#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Grants the agent its access to the Proxmox Host (ADR 0019): an SSH login with
# scoped sudo for writes, and an audit-only API token for reads. Run from the
# repo root; it writes only the HOPS_PROXMOX_* keys in .env.

TOTAL_STAGES=4
READER="hops-reader@pve"
TOKEN_NAME="hops"
TOKEN_ID="${READER}!${TOKEN_NAME}"

pve_ssh() {
  ssh -i "${HOPS_PROXMOX_SSH_KEY/#\~/$HOME}" -o BatchMode=yes -o ConnectTimeout=10 -o StrictHostKeyChecking=accept-new \
    "${HOPS_PROXMOX_SSH_USER}@${HOPS_PROXMOX_SSH_HOST}" "$@"
}

[[ -f .env.example && -f hosts.yaml ]] || { warn "run this from the repo root"; exit 1; }

banner "Proxmox Host: the agent's login and read token"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Address and SSH key"
say "The agent reaches the Proxmox Host over SSH with the same key it uses for the TrueNAS Host."
note "Keep console access to the Proxmox Host, so you can undo anything that cuts off SSH."
ask HOPS_PROXMOX_SSH_HOST "Proxmox Host address (name or IP):"
[[ -n "$HOPS_PROXMOX_SSH_HOST" ]] || { warn "an address is required"; exit 1; }
HOPS_PROXMOX_SSH_KEY=$(_existing HOPS_PROXMOX_SSH_KEY || true)
# shellcheck disable=SC2088 # .env keeps the literal ~, as .env.example does
[[ -n "$HOPS_PROXMOX_SSH_KEY" ]] || HOPS_PROXMOX_SSH_KEY=$(_existing HOPS_TRUENAS_SSH_KEY || echo "~/.ssh/homeops_agent_ed25519")
if [[ ! -f "${HOPS_PROXMOX_SSH_KEY/#\~/$HOME}.pub" ]]; then
  warn "no public key at ${HOPS_PROXMOX_SSH_KEY}.pub"
  ask HOPS_PROXMOX_SSH_KEY "Path to the agent's private key:"
  [[ -f "${HOPS_PROXMOX_SSH_KEY/#\~/$HOME}.pub" ]] || { warn "still no public key beside it"; exit 1; }
fi
write_env HOPS_PROXMOX_SSH_HOST "$HOPS_PROXMOX_SSH_HOST"
write_env HOPS_PROXMOX_SSH_KEY "$HOPS_PROXMOX_SSH_KEY"
pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "The agent's Linux user"
default_user=$(_existing HOPS_PROXMOX_SSH_USER || _existing HOPS_TRUENAS_SSH_USER || true)
if [[ -n "$default_user" ]]; then
  printf '  %sLogin name for the agent%s %s[Enter keeps %s]%s ' "$BOLD" "$RESET" "$DIM" "$default_user" "$RESET"
  read -r HOPS_PROXMOX_SSH_USER || true
  HOPS_PROXMOX_SSH_USER=${HOPS_PROXMOX_SSH_USER:-$default_user}
else
  ask HOPS_PROXMOX_SSH_USER "Login name for the agent:"
fi
[[ "$HOPS_PROXMOX_SSH_USER" =~ ^[a-z_][a-z0-9_-]*$ ]] || { warn "not a valid Linux user name"; exit 1; }

# The last rule the sudoers file gained; a login without it gets the root script again, which rewrites the file.
if pve_ssh sudo -n pvesh get /version >/dev/null 2>&1 && pve_ssh sudo -n -l tee /etc/pve/priv/notifications.cfg >/dev/null 2>&1; then
  say "The agent can already log in and run every allowed command; skipping the root script."
else
  printf -v pubkey_q '%q' "$(cat "${HOPS_PROXMOX_SSH_KEY/#\~/$HOME}.pub")"
  paste_file=$(mktemp)
  cat > "$paste_file" <<ROOTEOF
set -e; u='${HOPS_PROXMOX_SSH_USER}'; pub=${pubkey_q}
command -v sudo >/dev/null || apt-get install -y sudo
id "\$u" >/dev/null 2>&1 || useradd -m -s /bin/bash "\$u"
install -d -m 700 -o "\$u" -g "\$u" "/home/\$u/.ssh"
touch "/home/\$u/.ssh/authorized_keys"; grep -qxF "\$pub" "/home/\$u/.ssh/authorized_keys" || echo "\$pub" >> "/home/\$u/.ssh/authorized_keys"
chown "\$u:\$u" "/home/\$u/.ssh/authorized_keys"; chmod 600 "/home/\$u/.ssh/authorized_keys"
t=\$(command -v tee); f=\$(mktemp)
echo "\$u ALL=(root) NOPASSWD: \$(command -v pvesh), \$(command -v qm), \$(command -v pct), \$(command -v vzdump), \$(command -v pvesm) set truenas-backup --password, \$t /etc/pve/priv/notifications.cfg, \$t /etc/subuid, \$t /etc/subgid, \$t ^/etc/pve/lxc/[0-9]+[.]conf\$, \$t ^/var/lib/vz/snippets/[a-z0-9_-]+[.]sh\$" > "\$f"
visudo -cf "\$f" && install -m 440 "\$f" /etc/sudoers.d/homeops-agent; rm -f "\$f"; echo "agent login ready"
ROOTEOF
  open_url "https://${HOPS_PROXMOX_SSH_HOST}:8006"
  step "Sign in as root. Select the node under Datacenter, then click Shell."
  if command -v pbcopy >/dev/null 2>&1; then
    pbcopy < "$paste_file"; step "Paste (it's on your clipboard) and press Enter. It should end with 'agent login ready'."
  else
    step "Paste these lines and press Enter. They should end with 'agent login ready':"
    printf '\n%s\n' "$(cat "$paste_file")"
  fi
  rm -f "$paste_file"
  pause "Press Enter once it printed 'agent login ready'"
fi
pve_ssh sudo -n pvesh get /version >/dev/null 2>&1 || { warn "the agent can't run 'sudo -n pvesh' over SSH yet; fix that and re-run"; exit 1; }
if pve_ssh sudo -n true >/dev/null 2>&1; then
  warn "sudo -n allows commands outside the list; check /etc/sudoers.d on the Proxmox Host"; exit 1
fi
say "${GREEN}✓${RESET} SSH and scoped sudo work, and other commands are refused."
write_env HOPS_PROXMOX_SSH_USER "$HOPS_PROXMOX_SSH_USER"
pause

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "The read token"
say "Creating ${READER} with PVEAuditor on /, and its token '${TOKEN_NAME}' (privilege-separated)."
if ! pve_ssh sudo -n pvesh get "/access/users/${READER}" >/dev/null 2>&1; then
  pve_ssh sudo -n pvesh create /access/users --userid "${READER}" --comment "'Read-only API user for repo tooling'" >/dev/null
fi
pve_ssh sudo -n pvesh set /access/acl --path / --users "${READER}" --roles PVEAuditor >/dev/null
secret_saved=$(_existing HOPS_PROXMOX_PROXMOX_TOKEN_SECRET || true)
make_token=1
if token_json=$(pve_ssh sudo -n pvesh get "/access/users/${READER}/token/${TOKEN_NAME}" --output-format json 2>/dev/null); then
  privsep=$(printf '%s' "$token_json" | python3 -c 'import json,sys; print(int(json.load(sys.stdin).get("privsep", 1)))')
  if [[ "$privsep" != "1" ]]; then
    warn "the existing token is not privilege-separated, so it must be recreated"
    confirm "Delete and recreate it?" || exit 1
  elif [[ -n "$secret_saved" ]] && ! confirm "The token exists and .env has a secret. Replace both?"; then
    make_token=0
  elif [[ -z "$secret_saved" ]] && ! confirm "The token exists but .env has no secret for it. Delete and recreate it?"; then
    warn "a token secret is required"; exit 1
  fi
  if (( make_token )); then
    # Clear the saved secret first, so a failure below leaves .env visibly unconfigured, not holding a revoked secret.
    write_env HOPS_PROXMOX_PROXMOX_TOKEN_SECRET ""
    pve_ssh sudo -n pvesh delete "/access/users/${READER}/token/${TOKEN_NAME}" >/dev/null
  fi
fi
if (( make_token )); then
  HOPS_PROXMOX_PROXMOX_TOKEN_SECRET=$(pve_ssh sudo -n pvesh create "/access/users/${READER}/token/${TOKEN_NAME}" \
      --privsep 1 --comment "'repo tooling reads'" --output-format json \
    | python3 -c 'import json,sys; print(json.load(sys.stdin)["value"])')
  [[ -n "$HOPS_PROXMOX_PROXMOX_TOKEN_SECRET" ]] || { warn "no token secret came back"; exit 1; }
  write_env HOPS_PROXMOX_PROXMOX_TOKEN_SECRET "$HOPS_PROXMOX_PROXMOX_TOKEN_SECRET"
else
  HOPS_PROXMOX_PROXMOX_TOKEN_SECRET=$secret_saved
fi
pve_ssh sudo -n pvesh set /access/acl --path / --tokens "'${TOKEN_ID}'" --roles PVEAuditor >/dev/null
write_env HOPS_PROXMOX_PROXMOX_TOKEN_ID "$TOKEN_ID"
# Adding PVEAuditor never removes other roles, so check the token's effective privileges on every path.
auditor=$(pve_ssh sudo -n pvesh get /access/roles/PVEAuditor --output-format json)
effective=$(pve_ssh sudo -n pvesh get /access/permissions --userid "'${TOKEN_ID}'" --output-format json)
extra=$(AUDITOR="$auditor" EFFECTIVE="$effective" python3 - <<'CHECKEOF'
import json, os
def privs(v):
    if isinstance(v, dict): return set(v)  # values are propagate flags; a key at 0 is still granted
    if isinstance(v, list): return set(v)
    return {p for p in str(v).split(",") if p}
a = json.loads(os.environ["AUDITOR"])
allowed = privs(a.get("privs", a) if isinstance(a, dict) else a)
bad = sorted({f"{path}:{p}" for path, ps in json.loads(os.environ["EFFECTIVE"]).items() for p in privs(ps) - allowed})
print(" ".join(bad))
CHECKEOF
)
if [[ -n "$extra" ]]; then
  warn "the token holds privileges beyond PVEAuditor: ${extra}"
  warn "remove the other ACL entries for ${READER} and its token, then re-run"; exit 1
fi
say "${GREEN}✓${RESET} The token's effective privileges are PVEAuditor's only."
note "The secret went straight to .env and was never shown."
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "API URL and check"
url_default="https://${HOPS_PROXMOX_SSH_HOST}:8006"
url_saved=$(_existing HOPS_PROXMOX_PROXMOX_URL || true)
[[ -n "$url_saved" && "$url_saved" == *"//${HOPS_PROXMOX_SSH_HOST}"[:/]* ]] && url_default=$url_saved
printf '  %sAPI base URL%s %s[Enter keeps %s]%s ' "$BOLD" "$RESET" "$DIM" "$url_default" "$RESET"
read -r HOPS_PROXMOX_PROXMOX_URL || true
HOPS_PROXMOX_PROXMOX_URL=${HOPS_PROXMOX_PROXMOX_URL:-$url_default}
HOPS_PROXMOX_PROXMOX_URL=${HOPS_PROXMOX_PROXMOX_URL%/}
curl_api() {
  curl -sS -o /dev/null -w '%{http_code}' ${insecure:+-k} \
    -H @<(printf 'Authorization: PVEAPIToken=%s=%s\n' "$TOKEN_ID" "$HOPS_PROXMOX_PROXMOX_TOKEN_SECRET") "$@"
}
insecure=""
code=$(curl_api "${HOPS_PROXMOX_PROXMOX_URL}/api2/json/version" 2>/dev/null) || code="tls"
if [[ "$code" == "tls" || "$code" == "000" ]]; then
  warn "the HTTPS request failed, most likely a self-signed certificate"
  if confirm "Skip TLS verification for the Proxmox API (HOPS_PROXMOX_PROXMOX_INSECURE=1)?"; then
    insecure=1
    code=$(curl_api "${HOPS_PROXMOX_PROXMOX_URL}/api2/json/version" 2>/dev/null) || code="000"
  fi
fi
[[ "$code" == "200" ]] || { warn "GET /version with the token returned ${code}; expected 200"; exit 1; }
say "${GREEN}✓${RESET} The token can read."
wcode=$(curl_api -X POST --data-urlencode "poolid=hops-write-probe" "${HOPS_PROXMOX_PROXMOX_URL}/api2/json/pools" 2>/dev/null) || wcode="000"
if [[ "$wcode" != "403" ]]; then
  warn "a write with the token returned ${wcode}, not 403; the token can write"
  (( wcode == 200 )) && warn "remove the pool 'hops-write-probe' it created, then narrow the token's ACL"
  exit 1
fi
say "${GREEN}✓${RESET} The token is refused a write (403)."
write_env HOPS_PROXMOX_PROXMOX_URL "$HOPS_PROXMOX_PROXMOX_URL"
write_env HOPS_PROXMOX_PROXMOX_INSECURE "${insecure:-0}"
pause

finish
